def solve(tokens):
    stack = []
    for token in tokens:
        if token not in {'+', '-', '*', '/'}:
            stack.append(int(token))
            continue
        right = stack.pop()
        left = stack.pop()
        if token == '+':
            stack.append(left + right)
        elif token == '-':
            stack.append(left - right)
        elif token == '*':
            stack.append(left * right)
        else:
            value = abs(left) // abs(right)
            if (left < 0) != (right < 0):
                value = -value
            stack.append(value)
    return stack[-1]

